    SparqlRecord.add_member(:data, Smithy::Schema::Shapes::ShapeRef.new(shape: SparqlData, location_name: 'data', traits: {"smithy.api#documentation" => "<p>The serialized SPARQL change record. The serialization formats of each record are described in more detail in <a href=\"https://docs.aws.amazon.com/neptune/latest/userguide/streams-change-formats.html\">Serialization Formats in Neptune Streams</a>.</p>", "smithy.api#required" => {}}))
